"use client";

import { useId, useState } from "react";
import Image from "next/image";
import { useTranslations } from "next-intl";
import testimonialData from "@/data/testimonials.json";

interface TestimonialsProps {
  type: "member" | "sustainer";
}

const TestimonialCollection = ({ type }: TestimonialsProps) => {
  const t = useTranslations("Testimonials");
  const headingId = useId();
  const quoteId = useId();
  const testimonials = testimonialData.filter((item) => item.type === type);
  const [selected, setSelected] = useState(0);
  const testimonial = testimonials[selected];

  if (!testimonial) return null;

  return (
    <section className="border-y border-white/10 bg-[#10052d] py-16 text-white sm:py-20">
      <div className="mx-auto grid max-w-7xl gap-10 px-6 sm:px-8 lg:grid-cols-[280px_1fr] lg:gap-16">
        <div>
          <p className="mb-3 font-mono text-xs tracking-[0.2em] text-[#ff91b7]">
            ECLIPSE ADOPTIUM
          </p>
          <h2
            id={headingId}
            className="mb-7 max-w-sm text-3xl font-semibold leading-tight tracking-tight sm:text-4xl"
          >
            {t("title")}
          </h2>
          <div
            role="group"
            aria-labelledby={headingId}
            className="grid grid-cols-3 gap-2 lg:grid-cols-1 lg:gap-3"
          >
            {testimonials.map((item, index) => (
              <button
                key={item.companyName}
                type="button"
                aria-label={item.companyName}
                aria-pressed={selected === index}
                aria-controls={quoteId}
                onClick={() => setSelected(index)}
                className={`flex min-h-16 min-w-0 items-center justify-center rounded-xl border p-3 transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink lg:justify-start lg:px-5 ${
                  selected === index
                    ? "border-pink/50 bg-white/5"
                    : "border-transparent hover:border-white/15 hover:bg-white/5"
                }`}
              >
                <span
                  className={`relative block h-8 w-28 max-w-full ${
                    selected === index ? "opacity-100" : "opacity-50"
                  }`}
                >
                  <Image
                    src={item.companyLogo}
                    alt=""
                    fill
                    sizes="112px"
                    className="object-contain brightness-0 invert lg:object-left"
                  />
                </span>
              </button>
            ))}
          </div>
        </div>

        <figure
          id={quoteId}
          aria-live="polite"
          aria-atomic="true"
          className="m-0 min-w-0 border-t border-white/10 pt-8 lg:border-l lg:border-t-0 lg:pl-12 lg:pt-0"
        >
          <svg
            className="mb-6 h-9 w-9 text-pink"
            viewBox="0 0 24 27"
            fill="currentColor"
            aria-hidden="true"
          >
            <path d="M14.017 18L14.017 10.609C14.017 4.905 17.748 1.039 23 0L23.995 2.151C21.563 3.068 20 5.789 20 8H24V18H14.017ZM0 18V10.609C0 4.905 3.748 1.038 9 0L9.996 2.151C7.563 3.068 6 5.789 6 8H9.983L9.983 18L0 18Z" />
          </svg>
          <blockquote className="mb-8">
            <p className="mb-0 text-xl font-normal leading-relaxed tracking-tight text-white/90 sm:text-2xl lg:min-h-[216px]">
              &ldquo;{testimonial.quote}&rdquo;
            </p>
          </blockquote>
          <figcaption className="flex items-center gap-4 border-t border-white/10 pt-6">
            <Image
              src={testimonial.image}
              alt=""
              width={48}
              height={48}
              className="h-12 w-12 shrink-0 rounded-full object-cover"
            />
            <div className="min-w-0">
              <p className="mb-1 text-sm font-semibold text-white">
                {testimonial.name}
              </p>
              <p className="mb-0 text-xs leading-relaxed text-grey">
                {testimonial.role}
              </p>
            </div>
          </figcaption>
        </figure>
      </div>
    </section>
  );
};

const Testimonials = ({ type }: TestimonialsProps) => (
  <TestimonialCollection key={type} type={type} />
);

export default Testimonials;
